from copy import deepcopy

def solve(input_grid):
    output = deepcopy(input_grid)
    h, w = len(output), len(output[0])

    int_top, int_bottom = 3, 6
    int_left, int_right = 3, 6

    markers = []
    for r in range(h):
        for c in range(w):
            if output[r][c] != 0:
                if not (2 <= r <= 7 and 2 <= c <= 7):
                    markers.append((r, c, output[r][c]))

    # temp left (eom: cols 3-4 from left side markers) and temp right (cols 5-6 from right side)
    temp_left = []
    temp_right = []

    for mr in markers:
        if mr[1] <= 3:  # left-side marker (col 0-3)
            row, col, val = mr
            if mr in [m for m in markers if m[0] < 2]:  # above
                temp_left.append(val)
            elif mr in [m for m in markers if m[0] > 7]:  # below
                temp_left.append(val)
        elif mr[1] >= 6:  # right-side marker (col 5-9)
            row, col, val = mr
            if mr in [m for m in markers if m[0] < 2]:
                temp_right.append(val)
            elif mr in [m for m in markers if m[0] > 7]:
                temp_right.append(val)

    # temp_left = [left-top, left-bottom], temp_right = [right-top, right-bottom]
    # Each is a list of values for top/bottom

    # Clear interior
    for r in range(int_top, int_bottom+1):
        for c in range(int_left, int_right+1):
            output[r][c] = 0

    # Fill
    # For each column half, set values based on temp
    if temp_left:
        top_val_l = temp_left[0]  # any, all should be same
        bot_val_l = temp_left[-1]
        for r in range(int_top, int_top+2):
            for c in range(3, 5):
                output[r][c] = top_val_l
        for r in range(int_bottom-1, int_bottom+1):
            for c in range(3, 5):
                output[r][c] = bot_val_l

    if temp_right:
        top_val_r = temp_right[0]
        bot_val_r = temp_right[-1]
        for r in range(int_top, int_top+2):
            for c in range(5, 7):
                output[r][c] = top_val_r
        for r in range(int_bottom-1, int_bottom+1):
            for c in range(5, 7):
                output[r][c] = bot_val_r

    return output

