def solve_v5(input_grid, h, w):
    output = [row[:] for row in input_grid]

    int_top, int_bottom = 3, 6

    markers = []
    for r in range(h):
        for c in range(w):
            if output[r][c] != 0 and not (2 <= r <= 7 and 2 <= c <= 7):
                markers.append((r, c, output[r][c]))

    # Clear interior
    for r in range(int_top, int_bottom+1):
        for c in range(3, 7):
            output[r][c] = 0

    top_vals = sorted([m[2] for m in markers if m[0] < 2])
    bot_vals = sorted([m[2] for m in markers if m[0] > 7])

    if not top_vals and not bot_vals:
        return output

    if len(top_vals) > 0 and len(bot_vals) > 0:
        top_val = top_vals[0]
        bot_val = bot_vals[0]
    elif len(top_vals) > len(bot_vals):
        top_val = top_vals[0]
        bot_val = top_vals[1] if len(top_vals) > 1 else top_val
    elif len(bot_vals) > len(top_vals):
        bot_val = bot_vals[0]
        top_val = bot_vals[1] if len(bot_vals) > 1 else bot_val
    else:
        left_markers = [m for m in markers if m[1] <= 3]
        right_markers = [m for m in markers if m[1] >= 6]
        top_val = left_markers[0][2] if left_markers else right_markers[0][2]
        bot_val = bot_vals[0] if bot_vals else top_val

    # Check same side
    left_cols = [m[1] for m in markers if m[1] <= 3]
    right_cols = [m[1] for m in markers if m[1] >= 6]
    same_side = (len(left_cols) + len(right_cols) > 0 and (len(left_cols) == 0 or len(right_cols) == 0))

    # Assign
    # Left interior:
    #   - Same side: top half gets bot_val, bottom half gets top_val
    #   - Different sides: top half gets top_val, bottom half gets bot_val
    # Right interior: always vertically inverted relative to left

    for r in range(int_top, int_top+2):  # top
        for c in range(3, 5):
            if same_side:
                output[r][c] = bot_val
            else:
                output[r][c] = top_val
        for c in range(5, 7):
            # Right interior is inverted: opposite of left
            if same_side:
                output[r][c] = top_val
            else:
                output[r][c] = bot_val

    for r in range(int_bottom-1, int_bottom+1):  # bottom
        for c in range(3, 5):
            if same_side:
                output[r][c] = top_val
            else:
                output[r][c] = bot_val
        for c in range(5, 7):
            # Right interior is inverted
            if same_side:
                output[r][c] = bot_val
            else:
                output[r][c] = top_val

    return output

